// Solder Sip Enclosure - Procedural OpenSCAD
$fn = 40;
wall = 2.0;
inner_x = 124.0;
inner_y = 92.0;
inner_z = 36.0;
outer_x = inner_x + 2*wall;
outer_y = inner_y + 2*wall;
outer_z = inner_z + 2*wall;

module base_enclosure() {
  difference() {
    cube([outer_x, outer_y, outer_z], center = false);
    translate([wall, wall, wall])
      cube([inner_x, inner_y, inner_z + 1], center = false);
    // USB port cutout
    translate([-1, 15, wall + 3])
      cube([wall + 2, 13, 11]);
    // DC barrel jack cutout
    translate([-1, 40, wall + 2])
      cube([wall + 2, 10, 11]);
    // Sensor probe cable gland slot
    translate([outer_x - wall - 1, 30, wall + 5])
      cube([wall + 2, 12, 8]);
  }
  // Uno standoffs (M3)
  translate([wall + 14.0, wall + 2.5, wall]) standoff();
  translate([wall + 15.2, wall + 50.8, wall]) standoff();
  translate([wall + 66.0, wall + 7.6, wall]) standoff();
  translate([wall + 66.0, wall + 35.5, wall]) standoff();
}

module standoff() {
  difference() {
    cylinder(r = 3.2, h = 4.0);
    cylinder(r = 1.4, h = 4.5);
  }
}

module snap_lid() {
  difference() {
    cube([outer_x, outer_y, wall + 2.0]);
    // OLED screen window cutout
    translate([wall + 42, wall + 42, -1])
      cube([26, 16, wall + 4]);
    // Ventilation grills
    for (i = [0:4]) {
      translate([wall + 80 + (i*3), wall + 20, -1])
        cube([1.5, 20, wall + 4]);
    }
  }
}

base_enclosure();
translate([0, outer_y + 15, 0]) snap_lid();

