#include <Wire.h>

// Pin definitions
const int MOISTURE_PIN = A0;
const int RELAY_PIN = 7;
const int DRY_THRESHOLD_PERCENT = 35;

void setup() {
  Serial.begin(9600);
  pinMode(RELAY_PIN, OUTPUT);
  digitalWrite(RELAY_PIN, LOW); // Relay off initially

  Serial.println(F("--- Solder Sip Plant Hydrator Initialized ---"));
  Serial.println(F("Sensor: Capacitive Soil Probe | Actuator: 5V Relay"));
}

void loop() {
  // Read analog moisture sensor (0-1023)
  // In air ~800 (dry), In water ~300 (wet)
  int rawValue = analogRead(MOISTURE_PIN);
  int moisturePercent = map(rawValue, 850, 300, 0, 100);
  moisturePercent = constrain(moisturePercent, 0, 100);

  Serial.print(F("MOISTURE: "));
  Serial.print(moisturePercent);
  Serial.print(F("% (raw: "));
  Serial.print(rawValue);
  Serial.print(F(") -> "));

  if (moisturePercent < DRY_THRESHOLD_PERCENT) {
    Serial.println(F("STATUS: DRY | PUMP_ACTIVE"));
    digitalWrite(RELAY_PIN, HIGH); // Turn pump ON
  } else {
    Serial.println(F("STATUS: OK | PUMP_IDLE"));
    digitalWrite(RELAY_PIN, LOW);  // Turn pump OFF
  }

  delay(1000);
}
